# Compression Script

# This script compresses files into a zip format.
import zipfile
import os

def compress_files(input_folder, output_filename):
    with zipfile.ZipFile(output_filename, 'w') as zipf:
        for root, dirs, files in os.walk(input_folder):
            for file in files:
                zipf.write(os.path.join(root, file), file)

if __name__ == '__main__':
    compress_files('inputs', 'outputs/example.zip')

